import torch
import torch.nn as nn
import torch.nn.functional as F

from mrq_code.utils import Identity, LinearNormalizedActivation, init_weights
from mrq_code.config import MRQConfig

class StateEncoder(nn.Module):
    def __init__(self, state_dim, image_observation_space=False, state_channels=3):
        super().__init__()
        self.image_observation_space = image_observation_space
        self.activation = self._get_activation_function(MRQConfig.ACTIVATION_FUNCTION)

        if self.image_observation_space:
            # For image inputs: four convolutional layers
            # Assuming 84x84 input as mentioned in paper
            self.cnn_layers = nn.Sequential(
                nn.Conv2d(state_channels, 32, 3, stride=2),
                self.activation,
                nn.Conv2d(32, 32, 3, stride=2),
                self.activation,
                nn.Conv2d(32, 32, 3, stride=2),
                self.activation,
                nn.Conv2d(32, 32, 3, stride=1),
                self.activation
            )
            # Calculate the output size of the CNN to determine input for linear layer
            # This assumes an 84x84 input, which results in 32 * 7 * 7 = 1568 features
            self.linear_project = LinearNormalizedActivation(1568, self.activation)
            self.final_layer = nn.Linear(1568, MRQConfig.ZS_DIM)
        else:
            # For vector inputs: three-layer MLP
            self.mlp = nn.Sequential(
                LinearNormalizedActivation(state_dim, self.activation),
                nn.Linear(MRQConfig.HIDDEN_DIM, MRQConfig.HIDDEN_DIM),
                LinearNormalizedActivation(MRQConfig.HIDDEN_DIM, self.activation),
                nn.Linear(MRQConfig.HIDDEN_DIM, MRQConfig.ZS_DIM),
                LinearNormalizedActivation(MRQConfig.ZS_DIM, self.activation)
            )

        self.apply(lambda m: init_weights(m, MRQConfig.WEIGHT_INITIALIZATION, MRQConfig.BIAS_INITIALIZATION))

    def _get_activation_function(self, name):
        if name == "ELU":
            return nn.ELU()
        elif name == "ReLU":
            return nn.ReLU()
        else:
            raise ValueError(f"Unknown activation function: {name}")

    def forward(self, state):
        if self.image_observation_space:
            # Normalize state for image inputs
            state = state / 255.0 - 0.5
            features = self.cnn_layers(state)
            features = features.reshape(features.size(0), -1) # Flatten
            zs = self.final_layer(features)
            return self.activation(nn.LayerNorm(zs.shape[-1]).to(zs.device)(zs))

        else:
            zs = self.mlp(state)
            return zs

class StateActionEncoder(nn.Module):
    def __init__(self, action_dim, zs_dim=MRQConfig.ZS_DIM):
        super().__init__()
        self.activation = self._get_activation_function(MRQConfig.ACTIVATION_FUNCTION)

        self.action_linear = nn.Linear(action_dim, MRQConfig.ZA_DIM)

        self.mlp = nn.Sequential(
            LinearNormalizedActivation(zs_dim + MRQConfig.ZA_DIM, MRQConfig.HIDDEN_DIM, self.activation),
            nn.Linear(MRQConfig.HIDDEN_DIM, MRQConfig.HIDDEN_DIM),
            LinearNormalizedActivation(MRQConfig.HIDDEN_DIM, self.activation),
            nn.Linear(MRQConfig.HIDDEN_DIM, MRQConfig.ZSA_DIM)
        )

        # Linear MDP Predictor - output_dim needs to predict reward (bins), next state embedding (zs_dim), terminal (1)
        # As mentioned in the README, output_dim needs careful construction
        self.model = nn.Linear(MRQConfig.ZSA_DIM, MRQConfig.REWARD_BINS + zs_dim + 1) 

        self.apply(lambda m: init_weights(m, MRQConfig.WEIGHT_INITIALIZATION, MRQConfig.BIAS_INITIALIZATION))

    def _get_activation_function(self, name):
        if name == "ELU":
            return nn.ELU()
        elif name == "ReLU":
            return nn.ReLU()
        else:
            raise ValueError(f"Unknown activation function: {name}")

    def forward(self, zs, action):
        # Process action input
        processed_action = self.activation(self.action_linear(action))

        # Concatenate state embedding and processed action
        zsa_input = torch.cat([zs, processed_action], dim=-1)

        # Process through MLP
        zsa = self.mlp(zsa_input)

        # Predict reward, next state embedding, and terminal signal
        predictions = self.model(zsa)

        # Split predictions into reward logits, next_zs, and terminal_logits
        reward_logits = predictions[..., :MRQConfig.REWARD_BINS]
        next_zs = predictions[..., MRQConfig.REWARD_BINS:-1]
        terminal_logits = predictions[..., -1]

        return reward_logits, next_zs, terminal_logits, zsa


